long long largestRectangleArea(vector<int>& h) {
    vector<pair<int,int>> st; long long best = 0; int n = h.size();
    for (int i = 0; i <= n; i++) {
        int x = i < n ? h[i] : 0, start = i;
        while (!st.empty() && st.back().second >= x) { auto [j, y] = st.back(); st.pop_back(); best = max(best, (long long)y * (i - j)); start = j; }
        st.push_back({start, x});
    }
    return best;
}
